export function OrdersPage({ orders }: { orders: readonly Order[] }) {
  const [query, setQuery] = useState('');
  return (
    <>
      <input aria-label="Filter" value={query} onChange={(event) => setQuery(event.target.value)} />
      <MemoPanel>
        <OrderSummary orders={orders} />
      </MemoPanel>
    </>
  );
}

export function OrdersTable({ orders, query }: { orders: readonly Order[]; query: string }) {
  const navigate = useNavigate();
  return (
    <table>
      <tbody>
        {orders.map((order) => (
          <OrderRow key={order.id} order={order} onOpen={(orderId) => navigate('/orders/' + orderId)} />
        ))}
      </tbody>
    </table>
  );
}

setOrders((previous) => {
  const order = previous.find((candidate) => candidate.id === event.orderId);
  if (order !== undefined) {
    order.status = event.status;
  }
  return [...previous];
});

